#!/usr/bin/env bash
# ── GATHER D1 — matriz completa de experimentos de destilacao ─────────────────
#
# Ponto do grid (fixo em TODOS os comandos): --dataset protozoan --split 1 --percentage 100
#   (verificado no disco: data/to_modules/new_split_parasito/protozoan-cysts/
#    splits_incremental/split1/data_descriptor_perc100.json existe)
# protozoan tem 7 classes, e o default do argparse e 9 -> --num-classes 7 em todo comando.
#
# Matriz: 5 modelos x 2 init x 3 caminhos de loss x 2 teacher = 60 comandos.
#
# arch-json difere por init (nao e engano de digitacao, e o que o ray script faz):
#   init random -> ch24_30_48_a0.5_f5  (larguras corretas: protozoan tem 30 canais)
#   init flim   -> ch24_32_48_a0.5_f5  (onde os pesos FLIM entregues vivem)
#
# conda: o shell que o tmux abre NAO tem o hook do conda (README.md L722), entao cada
# linha faz `source .../conda.sh` antes do `conda activate`, como em scripts/README.md L6.
#
# Cada linha e literal e copiavel isoladamente. Rode isto uma vez antes:

mkdir -p /dados/home/moliveira/Scalable_Hybrid_FLIM/logs


